contract VaultInvariantTest is Test {
    Vault vault;

    function setUp() public {
        vault = new Vault();
        targetContract(address(vault));
    }

    function invariant_SolvencyCheck() public view {
        assertGe(address(vault).balance, vault.totalDeposits());
    }
}

